import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- COMPONENTS ---

const Navbar = ({ cartCount }) => (
  <nav className="bg-white/95 backdrop-blur-md shadow-sm sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="w-full px-6 md:px-12"> 
      <div className="flex justify-between items-center h-20">

        {/* LOGO JIDID: Barq ⚡ + Design Modern */}
        <Link to="/" className="flex items-center space-x-3 group">
          <div className="bg-orange-600 p-2 rounded-xl shadow-lg transform group-hover:scale-110 transition duration-300">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="flex flex-col text-left">
            <span className="font-black text-2xl text-gray-900 leading-none tracking-tighter italic">
              FAST<span className="text-orange-600">DÉLICE</span>
            </span>
            <span className="text-[9px] font-bold text-gray-400 uppercase tracking-[0.2em]">Gastronomie Rapide</span>
          </div>
        </Link>

        <div className="hidden lg:flex items-center space-x-10 font-black text-gray-600 uppercase text-xs tracking-widest">
          <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
          <Link to="/about" className="hover:text-orange-600 transition">À Propos</Link>
        </div>

        <div className="flex items-center space-x-8">
          <Link to="/panier" className="relative group flex items-center text-gray-800 hover:text-orange-600 transition font-black text-xs uppercase tracking-widest">
            <div className="relative p-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              <span className="absolute top-0 right-0 bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center border-2 border-white">{cartCount}</span>
            </div>
            <span className="ml-1">Panier</span>
          </Link>
          <Link to="/login" className="bg-gray-900 text-white px-7 py-3 rounded-xl hover:bg-orange-600 transition duration-300 font-black text-xs uppercase tracking-widest shadow-lg">Connexion</Link>
        </div>
      </div>
    </div>
  </nav>
);

// Wrapper for common layout across pages
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen w-full flex flex-col items-center">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/75 backdrop-blur-[2px]"></div>
    </div>

    <div className="relative z-10 w-full max-w-7xl px-6 py-20">
      {title && <h2 className="text-6xl md:text-8xl font-black text-white text-center mb-16 italic tracking-tighter drop-shadow-2xl">{title}</h2>}
      {children}
    </div>
  </div>
);

// --- PAGES ---

const Home = () => (
  <PageLayout>
    <div className="text-center py-20">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-500">Délice</span></h1>
      <p className="text-xl md:text-3xl mb-12 font-medium text-gray-200 italic">Une fusion de rapidité et de raffinement.</p>
      <Link to="/menu" className="bg-orange-600 hover:bg-white hover:text-orange-600 text-white px-14 py-5 rounded-2xl text-xl font-black transition-all duration-300 shadow-2xl inline-block uppercase tracking-widest">Voir la Carte</Link>
    </div>
  </PageLayout>
);

const About = () => (
  <PageLayout title="À Propos">
    <div className="max-w-4xl mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3rem] text-white shadow-2xl">
      <h3 className="text-3xl font-black mb-6 text-orange-500 italic uppercase">Notre Vision</h3>
      <p className="text-lg leading-relaxed text-gray-200 mb-8 font-medium italic">
        Chez FastDélice, nous pensons que chaque repas est une expérience. Nous marions la vitesse de la vie moderne avec l'exigence de la haute gastronomie. Nos chefs travaillent avec passion pour transformer des produits simples en chefs-d'œuvre culinaires.
      </p>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-left">
        <div className="bg-white/5 p-8 rounded-3xl border border-white/10">
          <div className="text-orange-500 mb-4">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
          </div>
          <h4 className="text-white font-black uppercase text-sm mb-2">Ingrédients Bios</h4>
          <p className="text-sm text-gray-400">Directement de la ferme à votre assiette.</p>
        </div>
        <div className="bg-white/5 p-8 rounded-3xl border border-white/10">
          <div className="text-orange-500 mb-4">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <h4 className="text-white font-black uppercase text-sm mb-2">Livraison Flash</h4>
          <p className="text-sm text-gray-400">Votre commande chez vous en moins de 20 minutes.</p>
        </div>
      </div>
    </div>
  </PageLayout>
);

const Menu = ({ categories, addToCart }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDish, setSelectedDish] = useState(null);
  const navigate = useNavigate();

  const filteredItems = categories.flatMap(cat => 
    cat.dishes.map(dish => ({ ...dish, categoryName: cat.name }))
  ).filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const confirmOrder = (type) => {
    addToCart({ ...selectedDish, orderType: type });
    setSelectedDish(null);
    navigate('/panier');
  };

  return (
    <PageLayout title="La Carte">
      <div className="max-w-xl mx-auto mb-16 relative">
        <input type="text" placeholder="Pizza, Tacos, Burgers..." className="w-full px-14 py-5 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 outline-none focus:ring-4 focus:ring-orange-500/50 font-bold text-white placeholder-gray-400 transition" onChange={(e) => setSearchTerm(e.target.value)} />
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute left-5 top-1/2 -translate-y-1/2 text-orange-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredItems.map(item => (
          <div key={item.id} className="bg-white/10 backdrop-blur-xl border border-white/10 rounded-[2.5rem] overflow-hidden hover:scale-105 transition duration-500 shadow-2xl">
            <div className="h-64 bg-black/20 flex items-center justify-center text-7xl">{item.categoryName.toLowerCase().includes('pizza') ? '🍕' : '🌮'}</div>
            <div className="p-8 text-center text-white">
              <h3 className="text-2xl font-black mb-6 italic">{item.name}</h3>
              <div className="flex items-center justify-between mt-4">
                  <span className="text-2xl font-black text-orange-500">{item.price} DH</span>
                  <button onClick={() => setSelectedDish(item)} className="bg-white text-gray-900 px-6 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-orange-600 hover:text-white transition shadow-lg tracking-widest">Commander</button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {selectedDish && (
        <div className="fixed inset-0 bg-black/85 backdrop-blur-lg z-[100] flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-white/10 rounded-[3rem] p-12 max-w-sm w-full shadow-2xl text-center">
            <h3 className="text-3xl font-black text-white mb-8 italic">Mode de service</h3>
            <div className="space-y-4">
              <button onClick={() => confirmOrder('Sur Place')} className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black text-lg hover:bg-orange-700 transition">🍽️ Sur Place</button>
              <button onClick={() => confirmOrder('Emporter')} className="w-full py-5 bg-white text-gray-900 rounded-2xl font-black text-lg hover:bg-gray-200 transition">🥡 À Emporter</button>
              <button onClick={() => setSelectedDish(null)} className="w-full py-3 text-gray-500 font-bold text-xs uppercase mt-4">Retour</button>
            </div>
          </div>
        </div>
      )}
    </PageLayout>
  );
};

const PanierPage = ({ cart }) => (
  <PageLayout title="Mon Panier">
    {cart.length === 0 ? (
      <div className="text-center py-20 text-white/20 font-black text-5xl italic tracking-tighter">Votre panier attend vos envies... 🛒</div>
    ) : (
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3rem] shadow-2xl max-w-2xl mx-auto text-white">
        {cart.map((item, index) => (
          <div key={index} className="flex justify-between items-center py-6 border-b border-white/5">
            <div>
              <h3 className="text-2xl font-black italic">{item.name}</h3>
              <span className="text-orange-500 text-[10px] font-black uppercase tracking-[0.2em]">{item.orderType}</span>
            </div>
            <span className="text-2xl font-black text-orange-500">{item.price} DH</span>
          </div>
        ))}
        <div className="mt-10 pt-10 border-t-2 border-orange-600 flex justify-between items-center">
          <span className="text-3xl font-black italic">TOTAL</span>
          <span className="text-4xl font-black text-orange-500">{cart.reduce((total, item) => total + parseFloat(item.price), 0).toFixed(2)} DH</span>
        </div>
        <button className="w-full mt-12 bg-orange-600 text-white py-6 rounded-2xl font-black text-xl hover:bg-orange-700 transition shadow-2xl uppercase tracking-widest">Valider la Commande</button>
      </div>
    )}
  </PageLayout>
);

// --- MAIN APP ---

function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.error(err));
  }, []);

  const addToCart = (item) => setCart([...cart, item]);

  return (
    <Router>
      <div className="min-h-screen bg-black overflow-x-hidden">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} />} />
          <Route path="/about" element={<About />} />
          <Route path="/panier" element={<PanierPage cart={cart} />} />
          <Route path="/login" element={<PageLayout title="Connexion"><div className="h-40"></div></PageLayout>} />
        </Routes>
        <footer className="relative z-10 bg-black py-16 text-center text-gray-600 font-bold uppercase tracking-[0.4em] text-[9px] border-t border-white/5">
          © 2026 FAST DÉLICE. Excellence Culinaire.
        </footer>
      </div>
    </Router>
  );
}

export default App;
